INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6200, 'statute of limitations', '/ˈstætjuːt əv ˌlɪmɪˈteɪʃənz/', 'noun', '{"zh-TW":["訴訟時效；起訴限期"],"en":["the time limit within which legal action must be taken"]}', NULL, 'statute of limitations period / within the statute of limitations', '[{"en":"The lawsuit was filed before the statute of limitations expired.","zh-TW":"訴訟在訴訟時效到期前提起。"},{"en":"The statute of limitations for contract disputes varies by jurisdiction.","zh-TW":"合約爭議的訴訟時效因司法管轄區而異。"}]', NULL, NULL, 5, 6200, NULL),
(6201, 'statutory', '/ˈstætʃətɔːri/', 'adjective', '{"zh-TW":["法定的；依法規定的"],"en":["required or imposed by law"]}', NULL, 'statutory requirement / statutory obligations / statutory holiday', '[{"en":"Companies must comply with all statutory reporting requirements.","zh-TW":"公司必須遵守所有法定報告要求。"},{"en":"Employees are entitled to statutory sick pay under labor law.","zh-TW":"員工依勞動法有權獲得法定病假工資。"}]', '{"adverb":"statutorily","noun":"statute"}', NULL, 3, 6201, 935),
(6202, 'statutory requirement', '/stəˈtjuːtəri rɪˈkwaɪərmənt/', 'noun', '{"zh-TW":["法定要求"],"en":["an obligation imposed by law that must be fulfilled"]}', NULL, 'comply with statutory requirements / meet statutory requirements', '[{"en":"All employers must comply with statutory requirements for minimum wage.","zh-TW":"所有雇主必須遵守最低工資的法定要求。"},{"en":"Failure to meet statutory requirements can result in criminal charges.","zh-TW":"未能達到法定要求可能導致刑事指控。"}]', NULL, NULL, 5, 6202, NULL),
(6203, 'stay', '/steɪ/', 'verb', '{"zh-TW":["停留；保持"],"en":["to remain in a place","to continue in a state"]}', NULL, 'stay focused / stay in touch', '[{"en":"Stay focused on the goals.","zh-TW":"專注於目標。"},{"en":"Let''s stay in touch.","zh-TW":"讓我們保持聯繫。"}]', '{"verb":"stay","noun":"stay"}', NULL, 1, 6203, NULL),
(6204, 'staycation', '/''steɪˌkeɪʃən/', 'noun', '{"zh-TW":["宅度假；在家度假"],"en":["a vacation spent at home or in one''s local area rather than traveling abroad"]}', NULL, 'enjoy a staycation / plan a staycation / budget staycation', '[{"en":"During the staycation, she explored museums and restaurants in her own city.","zh-TW":"在宅度假期間，她探索了自己城市的博物館和餐廳。"},{"en":"A staycation can be just as refreshing as an overseas trip.","zh-TW":"宅度假可以和海外旅行一樣令人精神煥發。"}]', NULL, NULL, 4, 6204, NULL),
(6205, 'stayover', '/ˈsteɪoʊvər/', 'noun', '{"zh-TW":["延長住宿"],"en":["a guest who extends their stay beyond the original checkout date"]}', NULL, 'process a stayover / stayover extension', '[{"en":"She requested a stayover to extend her booking by one night.","zh-TW":"她要求延長住宿，將預訂延長一晚。"},{"en":"Stayovers are handled automatically if the room is available.","zh-TW":"如果房間有空，延長住宿將自動處理。"}]', NULL, NULL, 3, 6205, NULL),
(6206, 'steadfast', '/''stedfɑːst/', 'adjective', '{"zh-TW":["堅定的；不動搖的"],"en":["resolutely or dutifully firm and unwavering"]}', NULL, 'steadfast commitment / steadfast belief / steadfast support', '[{"en":"He remained steadfast in his commitment to quality throughout his career.","zh-TW":"他在整個職業生涯中對質量的承諾保持堅定不移。"},{"en":"Steadfast leadership during uncertain times builds trust and confidence.","zh-TW":"在不確定時期的堅定領導能夠建立信任和信心。"}]', '{"adverb":"steadfastly","noun":"steadfastness"}', NULL, 3, 6206, NULL),
(6207, 'steady', '/ˈstedi/', 'adjective', '{"zh-TW":["穩定的；持續的"],"en":["regular and continuous; not changing"]}', NULL, 'steady growth / steady income / steady progress', '[{"en":"The company has shown steady growth over five years.","zh-TW":"公司在五年內呈現穩定增長。"},{"en":"We are making steady progress on the project.","zh-TW":"我們在專案上穩步前進。"}]', '{"noun":"steadiness","adjective":"steady","adverb":"steadily"}', NULL, 2, 6207, NULL),
(6208, 'steep', '/stiːp/', 'adjective', '{"zh-TW":["陡峭的；急劇的"],"en":["rising or falling sharply; very high"]}', NULL, 'steep increase / steep decline / steep price', '[{"en":"There was a steep decline in profits.","zh-TW":"利潤急劇下降。"},{"en":"The learning curve is quite steep.","zh-TW":"學習曲線相當陡峭。"}]', '{"adjective":"steep","adverb":"steeply"}', NULL, 2, 6208, NULL),
(6209, 'steering committee', '/ˈstɪərɪŋ kəˈmɪti/', 'noun', '{"zh-TW":["指導委員會"],"en":["a committee that oversees and directs a project"]}', NULL, 'form a steering committee / report to the steering committee', '[{"en":"The project''s steering committee meets monthly to review progress.","zh-TW":"項目指導委員會每月開會審查進展。"},{"en":"The steering committee approved the revised project scope.","zh-TW":"指導委員會批准了修訂後的項目範圍。"}]', NULL, NULL, 5, 6209, NULL),
(6210, 'stem', '/stem/', 'verb, noun', '{"zh-TW":["起源於；阻止","莖；幹"],"en":["to originate from; to stop","the main body of a plant"]}', NULL, 'stem from / stem the tide / stem cell', '[{"en":"The problem stems from poor planning.","zh-TW":"這個問題源於規劃不良。"},{"en":"We must stem the flow of losses.","zh-TW":"我們必須遏止虧損的趨勢。"}]', '{"noun":"stem","verb":"stem"}', NULL, 1, 6210, NULL),
(6211, 'step', '/stɛp/', 'noun', '{"zh-TW":["步驟；一步"],"en":["a movement of the foot","a stage in a process"]}', NULL, 'step by step / next step', '[{"en":"Let''s go through the process step by step.","zh-TW":"讓我們一步一步地完成流程。"},{"en":"What is the next step?","zh-TW":"下一步是什麼？"}]', '{"noun":"step","verb":"step"}', NULL, 1, 6211, NULL),
(6212, 'stewardship', '/ˈstjuːədʃɪp/', 'noun', '{"zh-TW":["管理；托管責任"],"en":["the responsible management of something entrusted to one''s care"]}', NULL, 'environmental stewardship / financial stewardship / corporate stewardship', '[{"en":"Good environmental stewardship ensures natural resources are preserved for future generations.","zh-TW":"良好的環境管理確保自然資源為後代保護。"},{"en":"The board praised the CEO''s financial stewardship during the crisis.","zh-TW":"董事會讚揚了首席執行官在危機期間的財務管理。"}]', '{"noun2":"steward","verb":"steward"}', NULL, 4, 6212, NULL),
(6213, 'stigma', '/ˈstɪɡmə/', 'noun', '{"zh-TW":["污名；社會偏見"],"en":["a mark of disgrace associated with a particular circumstance or group"]}', NULL, 'social stigma / mental health stigma / overcome stigma', '[{"en":"Reducing stigma around mental illness encourages people to seek help.","zh-TW":"降低圍繞心理疾病的污名鼓勵人們尋求幫助。"},{"en":"Stigma against poverty prevents vulnerable people from accessing support.","zh-TW":"對貧困的污名使弱勢群體無法獲得支持。"}]', '{"verb":"stigmatize","adjective":"stigmatized"}', NULL, 2, 6213, NULL),
(6214, 'still', '/stɪl/', 'noun, adjective, adverb, verb', '{"zh-TW":["【主要意義-副詞】仍然；還是","【次要意義-名詞】蒸餾器（釀酒設備）","【次要意義-名詞】靜物畫；電影劇照","【次要意義-動詞】使平靜；使安靜"],"en":["[primary - adverb] up to this time; even now","[secondary - noun] apparatus for making alcohol by distillation","[secondary - noun] a single photograph from a film or video","[secondary - verb] to make quiet or calm"]}', NULL, 'still life / distilling still / still the crowd / keep still', '[{"en":"The director selected a still from the film for the promotional poster.","zh-TW":"導演從電影中選了一張劇照用於宣傳海報。"},{"en":"The company operates a whisky still in the Scottish Highlands.","zh-TW":"這家公司在蘇格蘭高地經營一台威士忌蒸餾器。"},{"en":"Her calm words stilled the anxious crowd.","zh-TW":"她平靜的話語讓焦慮的人群安靜下來。"}]', '{"noun":"stillness","adjective":"still"}', 'still 作名詞意為「蒸餾器」或「劇照」，動詞表「使平靜」，這些次要意義在 TOEIC 飲食業或媒體相關文章中偶爾出現，容易讓考生困惑。', 2, 6214, NULL),
(6215, 'stimulate', '/ˈstɪmjuleɪt/', 'verb', '{"zh-TW":["刺激；激勵"],"en":["to encourage activity or development"]}', NULL, 'stimulate growth / stimulate the economy / stimulate demand', '[{"en":"The government introduced measures to stimulate the economy.","zh-TW":"政府推出了刺激經濟的措施。"},{"en":"Lower prices stimulate consumer demand.","zh-TW":"較低的價格刺激了消費者需求。"}]', '{"noun":"stimulation, stimulus","verb":"stimulate","adjective":"stimulating"}', NULL, 3, 6215, NULL),
(6216, 'stipulate', '/ˈstɪpjʊleɪt/', 'verb', '{"zh-TW":["規定；明確要求"],"en":["to specify a condition or requirement as part of an agreement"]}', NULL, 'stipulate terms / stipulate conditions / as stipulated', '[{"en":"The contract stipulates that payment must be made within 30 days.","zh-TW":"合約規定付款必須在30天內完成。"},{"en":"Quality standards are clearly stipulated in the procurement guidelines.","zh-TW":"採購指南中明確規定了品質標準。"}]', '{"noun":"stipulation","adjective":"stipulated"}', NULL, 3, 6216, NULL),
(6217, 'stir-fry', '/''stɜːr fraɪ/', 'verb', '{"zh-TW":["大火炒；翻炒"],"en":["to fry ingredients quickly in a small amount of very hot oil while stirring constantly"]}', NULL, 'stir-fry vegetables / stir-fry with garlic / stir-fry in a wok', '[{"en":"She stir-fried the vegetables with ginger and soy sauce for a healthy dinner.","zh-TW":"她用薑和醬油翻炒了蔬菜，做了一頓健康的晚餐。"},{"en":"The best stir-fry requires a very hot wok and constant movement.","zh-TW":"最好的大火翻炒需要非常熱的鍋和不停地翻動。"}]', '{"noun":"stir-fry"}', NULL, 3, 6217, NULL),
(6218, 'stock', '/stɒk/', 'noun', '{"zh-TW":["存貨；股票","股票；庫存","儲備；進貨"],"en":["goods available for sale","shares in a company","shares in a company; goods kept for sale","to keep a supply of"]}', '{"root":{"text":"stock","meaning":"trunk/store (樹幹/儲存)"},"logic":"原指樹幹（根基），引申為儲存的貨物。"}', 'in stock / out of stock / stock market; stock market / in stock / out of stock / stock price', '[{"en":"Sorry, that item is out of stock.","zh-TW":"抱歉，那個商品缺貨了。"},{"en":"We need to restock the shelves.","zh-TW":"我們需要補貨上架。"},{"en":"The stock market rallied after the announcement.","zh-TW":"公告後股市反彈。"},{"en":"The item is currently out of stock.","zh-TW":"該商品目前缺貨。"}]', '{"verb":"stock","noun":"stockholder"}', NULL, 2, 6218, NULL),
(6219, 'stock exchange', '/stɒk ɪksˈtʃeɪndʒ/', 'noun', '{"zh-TW":["證券交易所"],"en":["a marketplace where securities are bought and sold"]}', NULL, 'listed on a stock exchange / major stock exchange', '[{"en":"The company listed its shares on the New York Stock Exchange.","zh-TW":"公司在紐約證券交易所上市。"},{"en":"Stock exchange regulations ensure fair trading practices.","zh-TW":"證券交易所法規確保公平的交易實踐。"}]', NULL, NULL, 5, 6219, NULL),
(6220, 'stock keeping unit', '/stɒk ˈkiːpɪŋ ˌjuːnɪt/', 'noun', '{"zh-TW":["庫存單位"],"en":["a unique identifier for each distinct product in inventory management"]}', NULL, 'assign a SKU / SKU management / track by SKU', '[{"en":"Each product variant has its own stock keeping unit.","zh-TW":"每個產品變體都有自己的庫存單位。"},{"en":"SKU management simplifies inventory tracking across warehouses.","zh-TW":"庫存單位管理簡化了跨倉庫的庫存追蹤。"}]', '{"abbreviation":"SKU"}', NULL, 5, 6220, NULL),
(6221, 'stock market', '/stɒk ˈmɑːrkɪt/', 'noun', '{"zh-TW":["股票市場；股市"],"en":["a market where shares of publicly listed companies are bought and sold"]}', NULL, 'invest in the stock market / stock market performance', '[{"en":"The stock market reacted negatively to the news.","zh-TW":"股市對這一消息作出了負面反應。"},{"en":"Stock market returns outpaced inflation over the long term.","zh-TW":"長期來看，股市回報超過了通貨膨脹。"}]', NULL, NULL, 4, 6221, NULL),
(6222, 'stock option', '/stɒk ˈɒpʃən/', 'noun', '{"zh-TW":["股票選擇權"],"en":["the right to buy company stock at a fixed price in the future"]}', NULL, 'exercise stock options / stock option plan / vest stock options', '[{"en":"The startup offered generous stock options to attract engineers.","zh-TW":"新創公司提供豐厚的股票選擇權吸引工程師。"},{"en":"Stock options vest over a four-year period.","zh-TW":"股票選擇權在四年內歸屬。"}]', '{"plural":"stock options"}', NULL, 4, 6222, NULL),
(6223, 'stock option plan', '/stɒk ˈɒpʃən plæn/', 'noun', '{"zh-TW":["股票選擇權計劃"],"en":["a benefit allowing employees to purchase company shares at a set price"]}', NULL, 'participate in a stock option plan / stock option plan grant', '[{"en":"The stock option plan attracted senior talent from competitors.","zh-TW":"股票選擇權計劃從競爭對手那裡吸引了高級人才。"},{"en":"Employees exercised their stock option plan shares after the IPO.","zh-TW":"首次公開招股後員工行使了股票選擇權計劃的股份。"}]', NULL, NULL, 5, 6223, NULL),
(6224, 'stock replenishment', '/stɒk rɪˈplenɪʃmənt/', 'noun', '{"zh-TW":["補貨；庫存補充"],"en":["the process of restoring stock levels to meet future demand"]}', NULL, 'trigger stock replenishment / stock replenishment cycle', '[{"en":"The inventory system sends automatic alerts for stock replenishment.","zh-TW":"庫存系統發送自動補貨提醒。"},{"en":"Timely stock replenishment prevents stockouts during peak demand.","zh-TW":"及時的補貨在需求高峰期間防止了缺貨。"}]', NULL, NULL, 5, 6224, NULL),
(6225, 'stock split', '/stɒk splɪt/', 'noun', '{"zh-TW":["股票分割；股票拆分"],"en":["a division of existing shares into multiple new shares at a lower price each"]}', NULL, 'announce a stock split / stock split ratio', '[{"en":"The company announced a 2-for-1 stock split to improve affordability.","zh-TW":"公司宣布進行2比1的股票分割以提高可負擔性。"},{"en":"A stock split increases the number of shares but does not change total market value.","zh-TW":"股票分割增加了股票數量，但不改變總市值。"}]', NULL, NULL, 4, 6225, NULL),
(6226, 'stomach', '/ˈstʌmək/', 'verb, noun', '{"zh-TW":["【主要意義-名詞】胃；腹部","【次要意義-動詞】忍受；消化（情感上難以接受的事）"],"en":["[primary - noun] the organ that digests food; the abdomen","[secondary - verb] to tolerate or endure something unpleasant"]}', NULL, 'cannot stomach / stomach an insult / stomach the idea', '[{"en":"Many employees could not stomach the sudden pay cut announcement.","zh-TW":"許多員工無法接受突然宣布的薪資削減。"},{"en":"He found it hard to stomach the unfair criticism from upper management.","zh-TW":"他發現很難忍受來自高層管理的不公平批評。"},{"en":"She could not stomach the idea of working under such poor conditions.","zh-TW":"她無法忍受在如此惡劣的條件下工作的想法。"}]', '{"adjective":"stomach-turning"}', '動詞 stomach（尤其用於否定句 cannot stomach）= 「無法忍受/難以接受」，常見於 TOEIC 閱讀描述員工反應或職場情境的文章，與名詞「胃」完全不同。', 3, 6226, NULL),
(6227, 'stop', '/stɒp/', 'verb', '{"zh-TW":["停止"],"en":["to cease moving or doing"]}', NULL, 'stop by / non-stop', '[{"en":"Please stop by my office later.","zh-TW":"請待會過來我的辦公室一趟。"},{"en":"We worked non-stop to finish on time.","zh-TW":"我們不停地工作以準時完成。"}]', '{"verb":"stop","noun":"stop","noun2":"stoppage"}', NULL, 1, 6227, NULL),
(6228, 'stopover', '/ˈstɒpoʊvər/', 'noun', '{"zh-TW":["過境停留"],"en":["a break in a journey at an intermediate point"]}', NULL, 'overnight stopover / planned stopover', '[{"en":"They had a stopover in Singapore on the way to London.","zh-TW":"他們前往倫敦途中在新加坡過境停留。"},{"en":"A stopover can be a chance to explore a new city.","zh-TW":"過境停留可以是探索新城市的機會。"}]', NULL, NULL, 3, 6228, NULL),
(6229, 'storage', '/ˈstɔːrɪdʒ/', 'noun', '{"zh-TW":["儲存；儲存空間","儲存；倉儲"],"en":["the keeping of things for future use","the keeping of goods in a designated place"]}', NULL, 'cloud storage / storage space; data storage / storage capacity / cold storage', '[{"en":"I need more storage on my phone.","zh-TW":"我手機需要更多儲存空間。"},{"en":"Cloud storage is convenient.","zh-TW":"雲端儲存很方便。"},{"en":"Cloud storage has become essential for businesses.","zh-TW":"雲端儲存已成為企業的必需。"},{"en":"The warehouse has limited storage capacity.","zh-TW":"倉庫的儲存容量有限。"}]', '{"verb":"store","noun":"storage, store"}', NULL, 3, 6229, 462),
(6230, 'store', '/stɔːr/', 'noun', '{"zh-TW":["商店；儲存"],"en":["a retail shop","to keep for future use","a place where goods are sold"]}', '{"root":{"text":"store","meaning":"restore/keep (保存)"},"logic":"保存物品的地方，即「商店」或「倉庫」。"}', 'in store / store data; department store / store manager', '[{"en":"We have big changes in store.","zh-TW":"我們即將有重大變化。"},{"en":"Data is stored in the cloud.","zh-TW":"數據儲存在雲端。"},{"en":"The store opens at 9 a.m.","zh-TW":"商店早上九點開門。"},{"en":"Store the food in a cool dry place.","zh-TW":"將食物儲存在陰涼乾燥處。"}]', '{"noun":"store","verb":"store","noun2":"storage"}', NULL, 2, 6230, NULL),
(6231, 'storm', '/stɔːrm/', 'noun', '{"zh-TW":["暴風雨"],"en":["violent weather with strong winds and rain"]}', '{"root":{"text":"storm","meaning":"disturbance (擾動)"},"logic":"指大氣的劇烈擾動。"}', 'thunderstorm / storm warning / weather the storm', '[{"en":"A powerful storm is heading toward the coast.","zh-TW":"一場強烈暴風雨正朝海岸移動。"},{"en":"The company weathered the financial storm.","zh-TW":"公司挺過了金融風暴。"}]', '{"adjective":"stormy","verb":"storm"}', NULL, 2, 6231, NULL),
(6232, 'story', '/ˈstɔːri/', 'noun', '{"zh-TW":["故事；樓層"],"en":["a narrative","a level of a building"]}', NULL, 'success story / cover story', '[{"en":"Our company has a great success story.","zh-TW":"我們公司有一個精彩的成功故事。"},{"en":"The office building is ten stories tall.","zh-TW":"辦公大樓有十層樓高。"}]', '{"noun":"story","noun2":"storyline"}', NULL, 2, 6232, NULL),
(6233, 'storyboard', '/ˈstɔːrɪbɔːrd/', 'noun', '{"zh-TW":["故事板；分鏡腳本"],"en":["a sequence of drawings representing the shots in a film or advertisement"]}', NULL, 'create a storyboard / detailed storyboard / storyboard approval', '[{"en":"The director presented a detailed storyboard to the production team.","zh-TW":"導演向製作團隊展示了詳細的分鏡腳本。"},{"en":"A clear storyboard helps communicate the visual vision of the project.","zh-TW":"清晰的故事板有助於傳達項目的視覺願景。"}]', '{"verb":"storyboard"}', NULL, 4, 6233, NULL),
(6234, 'straight-line depreciation', '/streɪt laɪn dɪˌpriːʃiˈeɪʃən/', 'noun', '{"zh-TW":["直線折舊法"],"en":["a depreciation method that spreads asset cost equally over its useful life"]}', NULL, 'use straight-line depreciation / straight-line depreciation rate', '[{"en":"Straight-line depreciation charges $10000 per year on a $100000 asset.","zh-TW":"直線折舊法對10萬元資產每年計提1萬元折舊。"},{"en":"Straight-line depreciation is simple to apply and widely used.","zh-TW":"直線折舊法簡單易用且廣泛使用。"}]', '{"opposite":"accelerated depreciation"}', NULL, 5, 6234, NULL),
(6235, 'straightforward', '/ˌstreɪtˈfɔːrwərd/', 'adjective', '{"zh-TW":["直截了當的；簡單的"],"en":["easy to understand; uncomplicated"]}', NULL, 'straightforward process / straightforward answer / fairly straightforward', '[{"en":"The application process is straightforward.","zh-TW":"申請流程很簡單。"},{"en":"He gave a straightforward answer to the question.","zh-TW":"他對問題給出了直截了當的回答。"}]', '{"adjective":"straightforward","adverb":"straightforwardly"}', NULL, 5, 6235, NULL),
(6236, 'stranded asset', '/ˈstrændɪd ˈæset/', 'noun', '{"zh-TW":["擱淺資產"],"en":["an asset that has suffered unexpected devaluation due to regulation, market shifts, or technology"]}', NULL, 'stranded asset risk / avoid stranded assets / stranded fossil fuel assets', '[{"en":"Fossil fuel companies face the risk of stranded assets in the energy transition.","zh-TW":"化石燃料公司在能源轉型中面臨擱淺資產的風險。"},{"en":"Investors are increasingly pricing in stranded asset risk.","zh-TW":"投資者越來越多地將擱淺資產風險納入定價。"}]', NULL, NULL, 5, 6236, NULL),
(6237, 'strata', '/''strɑːtə/', 'noun', '{"zh-TW":["分層產權；公寓管理委員會"],"en":["a system of property ownership in which individual units are owned while common areas are managed collectively"]}', NULL, 'strata fees / strata committee / strata rules', '[{"en":"Monthly strata fees cover maintenance of common areas such as lifts and lobbies.","zh-TW":"每月分層產權費用涵蓋電梯和大廳等公共區域的維護。"},{"en":"The strata committee voted to repaint the exterior of the building.","zh-TW":"分層產權委員會投票決定重新粉刷大樓外觀。"}]', NULL, NULL, 2, 6237, NULL),
(6238, 'strata title', '/''strɑːtə ˌtaɪtəl/', 'noun', '{"zh-TW":["分層產權；公寓分割產權"],"en":["a system of land title for multi-story buildings where each unit is individually owned"]}', NULL, 'strata title property / strata title management / buy under strata title', '[{"en":"She bought an apartment under a strata title, which gave her ownership of the unit.","zh-TW":"她以分層產權購買了一套公寓，給予她對該單元的所有權。"},{"en":"Strata title owners share responsibility for maintaining common areas.","zh-TW":"分層產權業主共同承擔維護公共區域的責任。"}]', NULL, NULL, 4, 6238, NULL),
(6239, 'strategic', '/strəˈtiːdʒɪk/', 'adjective', '{"zh-TW":["戰略性的；策略性的"],"en":["relating to the planning and directing of overall business goals"]}', NULL, 'strategic decision / strategic priority / strategic partnership', '[{"en":"The acquisition was described as a strategic move into new markets.","zh-TW":"此次收購被描述為進入新市場的戰略舉措。"},{"en":"Strategic thinking sets leaders apart from operational managers.","zh-TW":"戰略思維將領導者與運營管理者區分開來。"}]', '{"adverb":"strategically","noun":"strategy"}', NULL, 3, 6239, NULL),
(6240, 'strategic alliance', '/strəˈtiːdʒɪk əˈlaɪəns/', 'noun', '{"zh-TW":["策略聯盟"],"en":["a formal agreement between companies to pursue shared goals"]}', NULL, 'form a strategic alliance / strategic alliance partner', '[{"en":"The strategic alliance gave both firms access to new markets.","zh-TW":"策略聯盟讓兩家公司都能進入新市場。"},{"en":"A strategic alliance was signed to share technology.","zh-TW":"簽署了技術共享的策略聯盟協議。"}]', '{"verb":"ally","adjective":"allied"}', NULL, 5, 6240, NULL),
(6241, 'strategic fit', '/strəˈtiːdʒɪk fɪt/', 'noun', '{"zh-TW":["戰略契合度"],"en":["the degree to which a deal or partnership aligns with a company''s strategy"]}', NULL, 'assess strategic fit / strong strategic fit / strategic fit analysis', '[{"en":"The acquisition scored highly on strategic fit metrics.","zh-TW":"收購在戰略契合度指標上得分很高。"},{"en":"A lack of strategic fit was cited as the reason for abandoning the merger.","zh-TW":"缺乏戰略契合度被引用為放棄合併的原因。"}]', NULL, NULL, 5, 6241, NULL),
(6242, 'strategic initiative', '/strəˈtiːdʒɪk ɪˈnɪʃɪətɪv/', 'noun', '{"zh-TW":["戰略倡議；策略計劃"],"en":["an action plan designed to achieve a specific strategic objective"]}', NULL, 'launch a strategic initiative / lead a strategic initiative', '[{"en":"The company launched a strategic initiative to expand into Asia.","zh-TW":"公司啟動了一項拓展亞洲市場的戰略倡議。"},{"en":"Board members review strategic initiatives every quarter.","zh-TW":"董事會成員每季度審查戰略倡議。"}]', NULL, NULL, 5, 6242, NULL),
(6243, 'strategic investment', '/strəˈtiːdʒɪk ɪnˈvestmənt/', 'noun', '{"zh-TW":["戰略投資"],"en":["an investment made to achieve long-term strategic goals beyond financial returns"]}', NULL, 'make a strategic investment / strategic investment decision', '[{"en":"The company made a strategic investment in its competitor to gain access.","zh-TW":"公司對競爭對手進行了戰略投資以獲取市場准入。"},{"en":"Strategic investments are evaluated on qualitative as well as financial criteria.","zh-TW":"戰略投資根據定性和財務標準進行評估。"}]', NULL, NULL, 5, 6243, NULL),
(6244, 'strategic partner', '/strəˈtiːdʒɪk ˈpɑːrtnər/', 'noun', '{"zh-TW":["戰略夥伴"],"en":["an organization allied with another for shared strategic goals"]}', NULL, 'identify a strategic partner / work with a strategic partner', '[{"en":"The company found a strategic partner to enter the Chinese market.","zh-TW":"公司找到了一家戰略夥伴進入中國市場。"},{"en":"A strategic partner provides complementary skills and market access.","zh-TW":"戰略夥伴提供互補的技能和市場准入。"}]', NULL, NULL, 5, 6244, NULL),
(6245, 'strategic partnership', '/strəˈtiːdʒɪk ˈpɑːrtnərˌshɪp/', 'noun', '{"zh-TW":["戰略夥伴關係；策略合作"],"en":["a cooperative arrangement between two organizations to pursue shared objectives"]}', NULL, 'form a strategic partnership / strategic partnership agreement / benefit from a strategic partnership', '[{"en":"The two tech companies announced a strategic partnership to develop AI-powered healthcare tools.","zh-TW":"兩家科技公司宣布建立戰略夥伴關係，共同開發人工智慧醫療工具。"},{"en":"A strong strategic partnership can open doors to new markets and resources.","zh-TW":"強大的戰略夥伴關係可以打開進入新市場和獲取資源的大門。"}]', NULL, NULL, 5, 6245, NULL),
(6246, 'strategic plan', '/strəˈtiːdʒɪk plæn/', 'noun', '{"zh-TW":["戰略計劃"],"en":["a document outlining an organization long-term goals and how to achieve them"]}', NULL, 'develop a strategic plan / implement the strategic plan', '[{"en":"The company released a new five-year strategic plan.","zh-TW":"公司發布了新的五年戰略計劃。"},{"en":"The strategic plan focuses on technology and sustainability.","zh-TW":"戰略計劃聚焦於技術和可持續性。"}]', NULL, NULL, 5, 6246, NULL),
(6247, 'strategic planning', '/strəˈtiːdʒɪk ˈplænɪŋ/', 'noun', '{"zh-TW":["戰略規劃"],"en":["the process of defining a company''s direction and making decisions on resources"]}', NULL, 'strategic planning process / strategic planning cycle / annual strategic planning', '[{"en":"Strategic planning sessions are held annually at the executive retreat.","zh-TW":"戰略規劃會議每年在高管靜修時舉行。"},{"en":"Effective strategic planning ensures the company is prepared for future challenges.","zh-TW":"有效的戰略規劃確保公司為未來挑戰做好準備。"}]', '{"adjective":"strategic","verb":"plan strategically"}', NULL, 5, 6247, NULL),
(6248, 'strategic planning process', '/strəˈtiːdʒɪk ˈplænɪŋ ˈprɒses/', 'noun', '{"zh-TW":["戰略規劃流程"],"en":["the structured approach to defining organizational strategy and goals"]}', NULL, 'follow the strategic planning process / annual strategic planning process', '[{"en":"The strategic planning process involves SWOT analysis and goal-setting.","zh-TW":"戰略規劃流程涉及SWOT分析和目標設定。"},{"en":"Senior leaders participate in the annual strategic planning process.","zh-TW":"高層領導參與年度戰略規劃流程。"}]', NULL, NULL, 5, 6248, NULL),
(6249, 'strategic review', '/strəˈtiːdʒɪk rɪˈvjuː/', 'noun', '{"zh-TW":["戰略審查"],"en":["a formal evaluation of an organization''s strategy, performance, and direction"]}', NULL, 'conduct a strategic review / strategic review findings', '[{"en":"The board commissioned a strategic review of the company''s global operations.","zh-TW":"董事會委託進行了公司全球運營的戰略審查。"},{"en":"A strategic review may result in significant changes to the business model.","zh-TW":"戰略審查可能導致商業模式的重大變化。"}]', NULL, NULL, 5, 6249, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6250, 'strategy', '/ˈstrætədʒi/', 'noun', '{"zh-TW":["策略","策略；戰略"],"en":["a plan of action to achieve a long-term goal","a plan designed to achieve a long-term goal"]}', '{"root":{"text":"strat","meaning":"army (軍隊)"},"suffix":{"text":"-egy","meaning":"leading (引領)"},"logic":"引領軍隊的計畫，即「策略」。"}', 'marketing strategy / business strategy / develop a strategy; business strategy / marketing strategy / develop a strategy', '[{"en":"We need a new strategy to increase sales.","zh-TW":"我們需要新策略來增加銷售。"},{"en":"The company developed a long-term growth strategy.","zh-TW":"公司制定了長期成長策略。"},{"en":"The company revised its marketing strategy.","zh-TW":"公司修改了行銷策略。"},{"en":"We need a clear strategy for expansion.","zh-TW":"我們需要明確的擴展策略。"}]', '{"adjective":"strategic","adverb":"strategically","noun2":"strategist","noun":"strategy, strategist"}', NULL, 3, 6250, 222),
(6251, 'streaming', '/ˈstriːmɪŋ/', 'noun', '{"zh-TW":["串流"],"en":["transmitting data continuously over the internet"]}', NULL, 'video streaming / streaming service', '[{"en":"Streaming has replaced traditional TV.","zh-TW":"串流取代了傳統電視。"},{"en":"Which streaming service do you subscribe to?","zh-TW":"你訂閱了哪個串流服務？"}]', '{"verb":"stream"}', NULL, 3, 6251, NULL),
(6252, 'streamline', '/ˈstriːmlaɪn/', 'verb', '{"zh-TW":["精簡；使流暢"],"en":["to make a process more efficient"]}', NULL, 'streamline operations / streamline processes / streamline workflow', '[{"en":"The company streamlined its production process.","zh-TW":"公司精簡了生產流程。"},{"en":"New technology helps streamline daily operations.","zh-TW":"新技術有助於精簡日常營運。"}]', '{"verb":"streamline","adjective":"streamlined"}', NULL, 4, 6252, 723),
(6253, 'streamline operations', '/''striːmˌlaɪn ˌɒpəˌreɪʃənz/', 'phrase', '{"zh-TW":["精簡運營；優化業務操作"],"en":["to make business operations more efficient by eliminating unnecessary steps or processes"]}', NULL, 'streamline operations to / need to streamline operations / successfully streamline operations', '[{"en":"The company brought in a consultant to help streamline operations and reduce waste.","zh-TW":"公司聘請了一位顧問幫助精簡運營並減少浪費。"},{"en":"By streamlining operations, the factory was able to double its output.","zh-TW":"通過精簡運營，工廠能夠將產量翻倍。"}]', '{"verb":"streamline"}', NULL, 5, 6253, NULL),
(6254, 'streamlined', '/ˈstriːmlaɪnd/', 'adjective', '{"zh-TW":["精簡的；流線型的"],"en":["designed for efficiency; having smooth lines"]}', NULL, 'streamlined process / streamlined design / streamlined operations', '[{"en":"The new streamlined process saves two hours per day.","zh-TW":"新的精簡流程每天節省兩小時。"},{"en":"We implemented a streamlined approval system.","zh-TW":"我們實施了精簡的審批系統。"}]', '{"adjective":"streamlined","verb":"streamline"}', NULL, 4, 6254, NULL),
(6255, 'streamlined process', '/''striːmˌlaɪnd ˌprɒses/', 'noun', '{"zh-TW":["精簡流程；優化流程"],"en":["a process that has been made more efficient by removing unnecessary steps"]}', NULL, 'implement a streamlined process / benefit of a streamlined process / create a streamlined process', '[{"en":"The new software enabled a streamlined process for approving expense reports.","zh-TW":"新軟件為批准費用報告提供了精簡流程。"},{"en":"A streamlined process reduces time wasted on bureaucratic steps.","zh-TW":"精簡流程減少了在官僚步驟上浪費的時間。"}]', '{"adjective":"streamlined","verb":"streamline"}', NULL, 5, 6255, NULL),
(6256, 'street', '/striːt/', 'noun', '{"zh-TW":["街道"],"en":["a public road in a city or town"]}', NULL, 'Wall Street / main street', '[{"en":"Wall Street reacted positively to the news.","zh-TW":"華爾街對這個消息反應正面。"},{"en":"The store is on the main street.","zh-TW":"商店在主要街道上。"}]', '{"noun":"street"}', NULL, 2, 6256, NULL),
(6257, 'strength training', '/''streŋkθ ˌtreɪnɪŋ/', 'noun', '{"zh-TW":["力量訓練；重量訓練"],"en":["physical exercise designed to improve muscle strength and endurance"]}', NULL, 'start strength training / strength training routine / benefit of strength training', '[{"en":"Strength training helps prevent bone loss and improves posture.","zh-TW":"力量訓練有助於防止骨質流失並改善姿勢。"},{"en":"She added strength training to her routine to complement her cardio workouts.","zh-TW":"她在日常鍛煉中加入力量訓練，以補充有氧運動。"}]', NULL, NULL, 5, 6257, NULL),
(6258, 'strengthen', '/ˈstreŋθn/', 'verb', '{"zh-TW":["加強；增強"],"en":["to make or become stronger"]}', NULL, 'strengthen ties / strengthen the position / strengthen regulations', '[{"en":"The partnership will strengthen our market position.","zh-TW":"合作將加強我們的市場地位。"},{"en":"The government strengthened environmental regulations.","zh-TW":"政府加強了環境法規。"}]', '{"noun":"strength","verb":"strengthen","adjective":"strong"}', NULL, 4, 6258, NULL),
(6259, 'stress', '/stres/', 'noun, verb', '{"zh-TW":["壓力；緊張","強調"],"en":["mental or emotional pressure","to emphasize"]}', NULL, 'under stress / stress the importance / stress management', '[{"en":"She stressed the importance of meeting deadlines.","zh-TW":"她強調了遵守截止日期的重要性。"},{"en":"Many employees suffer from workplace stress.","zh-TW":"許多員工受到工作壓力的影響。"}]', '{"noun":"stress","verb":"stress","adjective":"stressful, stressed"}', NULL, 2, 6259, NULL),
(6260, 'stress testing', '/stres ˈtestɪŋ/', 'noun', '{"zh-TW":["壓力測試"],"en":["a simulation to evaluate how a portfolio or institution performs under adverse conditions"]}', NULL, 'conduct stress testing / regulatory stress testing / scenario stress testing', '[{"en":"Regulators require banks to conduct annual stress testing.","zh-TW":"監管機構要求銀行進行年度壓力測試。"},{"en":"Stress testing revealed vulnerabilities in the firm''s liquidity position.","zh-TW":"壓力測試揭示了公司流動性狀況中的弱點。"}]', '{"verb":"stress test","adjective":"stress-tested"}', NULL, 5, 6260, NULL),
(6261, 'stress-testing', '/stres ˈtestɪŋ/', 'noun', '{"zh-TW":["壓力測試"],"en":["testing a system to evaluate performance under extreme conditions"]}', NULL, 'conduct stress-testing / stress-testing scenario / regulatory stress-testing', '[{"en":"Annual stress-testing of banks ensures they can withstand economic shocks.","zh-TW":"銀行的年度壓力測試確保其能夠承受經濟衝擊。"},{"en":"Stress-testing software helps identify failure points before deployment.","zh-TW":"壓力測試軟件幫助在部署前識別故障點。"}]', '{"verb":"stress-test","adjective":"stress-tested"}', NULL, 5, 6261, NULL),
(6262, 'stretching', '/''stretʃɪŋ/', 'noun', '{"zh-TW":["伸展；拉伸"],"en":["the practice of flexing muscles and joints to improve flexibility and prevent injury"]}', NULL, 'do stretching / dynamic stretching / post-workout stretching', '[{"en":"Daily stretching reduces muscle tightness and improves range of motion.","zh-TW":"每日伸展可以減少肌肉緊繃並改善活動範圍。"},{"en":"She spends ten minutes on stretching after every workout session.","zh-TW":"她在每次訓練後花十分鐘進行伸展。"}]', '{"verb":"stretch"}', NULL, 4, 6262, NULL),
(6263, 'strict', '/strɪkt/', 'adjective', '{"zh-TW":["嚴格的；嚴謹的"],"en":["demanding that rules are obeyed"]}', NULL, 'strict regulations / strict deadline / strict compliance', '[{"en":"The company has strict policies on data privacy.","zh-TW":"公司對資料隱私有嚴格的政策。"},{"en":"Strict compliance with safety standards is required.","zh-TW":"必須嚴格遵守安全標準。"}]', '{"adjective":"strict","adverb":"strictly","noun":"strictness"}', NULL, 2, 6263, NULL),
(6264, 'strike', '/straɪk/', 'noun, verb', '{"zh-TW":["【主要意義-動詞/名詞】打擊；罷工","【次要意義-動詞】給……留下印象；使覺得","【次要意義-動詞】達成（協議）；達到","【次要意義-名詞】（油/礦）新發現"],"en":["[primary] to hit something; a work stoppage","[secondary - verb] to make a strong impression on someone","[secondary - verb] to reach an agreement or achieve a balance","[secondary - noun] a sudden discovery of oil, gold, or similar resources"]}', NULL, 'strike a deal / strike a balance / strike me as / go on strike / lucky strike', '[{"en":"After weeks of negotiation, both sides struck a deal on the new contract.","zh-TW":"經過數週的談判，雙方就新合約達成了協議。"},{"en":"It strikes me as odd that no one was informed of the policy change.","zh-TW":"沒有人被告知政策變更，這讓我覺得很奇怪。"},{"en":"Workers went on strike to protest against the proposed pay freeze.","zh-TW":"工人舉行罷工，抗議擬議中的薪酬凍結。"}]', '{"noun":"striker","adjective":"striking"}', 'strike a deal/balance（達成協議/取得平衡）、strike me as（讓我覺得）是 TOEIC 商業談判文章的高頻表達，go on strike（舉行罷工）也是常考詞彙。', 2, 6264, NULL),
(6265, 'stringently', '/''strɪndʒəntli/', 'adverb', '{"zh-TW":["嚴格地；嚴厲地"],"en":["in a strict, precise, and demanding manner"]}', NULL, 'enforce stringently / apply stringently / regulate stringently', '[{"en":"Environmental standards are stringently enforced in the manufacturing zone.","zh-TW":"製造區的環境標準受到嚴格執行。"},{"en":"The company stringently monitors supplier compliance with its ethical sourcing policy.","zh-TW":"公司嚴格監控供應商對其道德採購政策的遵守情況。"}]', '{"adjective":"stringent"}', NULL, 4, 6265, NULL),
(6266, 'strive', '/straɪv/', 'verb', '{"zh-TW":["努力；奮鬥"],"en":["to make great efforts to achieve something"]}', NULL, 'strive for excellence / strive to achieve / strive to improve', '[{"en":"We strive for excellence in customer service.","zh-TW":"我們在客戶服務方面追求卓越。"},{"en":"The team strives to meet all deadlines.","zh-TW":"團隊努力在所有截止日前完成工作。"}]', '{"verb":"strive"}', NULL, 2, 6266, NULL),
(6267, 'strong', '/strɒŋ/', 'adjective', '{"zh-TW":["強壯的；強大的"],"en":["having great power","solid and difficult to break"]}', NULL, 'strong demand / strong leadership', '[{"en":"There is strong demand for this product.","zh-TW":"這個產品需求強勁。"},{"en":"Strong leadership guided the company through the crisis.","zh-TW":"強有力的領導帶領公司度過了危機。"}]', '{"adjective":"strong","adverb":"strongly","noun":"strength","verb":"strengthen"}', NULL, 2, 6267, NULL),
(6268, 'structural adjustment', '/ˈstrʌktʃərəl əˈdʒʌstmənt/', 'noun', '{"zh-TW":["結構性調整"],"en":["major reforms to improve economic efficiency and competitiveness"]}', NULL, 'implement structural adjustment / structural adjustment program / structural adjustment costs', '[{"en":"Structural adjustment programs often require reducing government subsidies.","zh-TW":"結構性調整計畫通常需要減少政府補貼。"},{"en":"Developing countries underwent painful structural adjustment in the 1980s.","zh-TW":"發展中國家在1980年代經歷了痛苦的結構性調整。"}]', '{"verb":"adjust structurally","adjective":"structurally adjusted"}', NULL, 5, 6268, NULL),
(6269, 'structural change', '/ˈstrʌktʃərəl tʃeɪndʒ/', 'noun', '{"zh-TW":["結構性變化"],"en":["a fundamental shift in the way an economy or industry operates"]}', NULL, 'adapt to structural change / structural change in the market', '[{"en":"Digital commerce represents a structural change in retail.","zh-TW":"數位商務代表著零售業的結構性變化。"},{"en":"Structural change often displaces workers who must reskill.","zh-TW":"結構性變化往往使需要重新培訓的工人失業。"}]', NULL, NULL, 5, 6269, NULL),
(6270, 'structural survey', '/''strʌktʃərəl ˌsɜːrveɪ/', 'noun', '{"zh-TW":["結構檢測；房屋結構調查"],"en":["a detailed assessment of a building''s structural condition conducted by a qualified surveyor"]}', NULL, 'commission a structural survey / structural survey report / pass a structural survey', '[{"en":"A structural survey revealed significant cracks in the foundation of the old building.","zh-TW":"結構檢測發現舊建築地基上有明顯裂縫。"},{"en":"Buyers are advised to commission a structural survey before completing a purchase.","zh-TW":"建議買家在完成購買之前委託進行結構檢測。"}]', NULL, NULL, 5, 6270, NULL),
(6271, 'structural unemployment', '/ˈstrʌktʃərəl ˌʌnɪmˈplɔɪmənt/', 'noun', '{"zh-TW":["結構性失業"],"en":["unemployment caused by a mismatch between workers'' skills and available jobs"]}', NULL, 'address structural unemployment / reduce structural unemployment / measure structural unemployment', '[{"en":"Automation creates structural unemployment when workers lack the skills demanded by new industries.","zh-TW":"當工人缺乏新興行業所需的技能時，自動化會造成結構性失業。"},{"en":"Retraining programs are designed to address structural unemployment by upgrading worker skills.","zh-TW":"再培訓計畫旨在通過提升工人技能來解決結構性失業問題。"}]', NULL, NULL, 5, 6271, NULL),
(6272, 'structural violence', '/ˈstrʌktʃərəl ˈvaɪələns/', 'noun', '{"zh-TW":["結構性暴力"],"en":["harm caused by social structures and institutions rather than direct action"]}', NULL, 'structural violence in healthcare / address structural violence / structural violence theory', '[{"en":"Paul Farmer''s work showed how poverty and racism constitute structural violence.","zh-TW":"保羅·法默的工作表明了貧困和種族主義如何構成結構性暴力。"},{"en":"Structural violence is embedded in systems that prevent basic needs from being met.","zh-TW":"結構性暴力嵌入於阻止基本需求得到滿足的系統中。"}]', NULL, NULL, 5, 6272, NULL),
(6273, 'structure', '/ˈstrʌktʃər/', 'noun, verb', '{"zh-TW":["結構；組織","構建；組織"],"en":["the way something is organized","to arrange in a systematic way"]}', NULL, 'organizational structure / cost structure / well-structured', '[{"en":"The company restructured its organizational structure.","zh-TW":"公司重組了其組織結構。"},{"en":"The report is well-structured and easy to follow.","zh-TW":"報告結構完善，易於理解。"}]', '{"noun":"structure, restructuring","verb":"structure, restructure","adjective":"structural"}', NULL, 3, 6273, 223),
(6274, 'structured finance', '/ˈstrʌktʃəd ˈfaɪnæns/', 'noun', '{"zh-TW":["結構性金融"],"en":["complex financial instruments created to redistribute risk, such as CDOs and MBS"]}', NULL, 'structured finance product / structured finance market / structured finance deal', '[{"en":"Structured finance instruments allowed banks to distribute mortgage risk to capital markets.","zh-TW":"結構性金融工具使銀行能夠將抵押貸款風險分散到資本市場。"},{"en":"The collapse of structured finance markets in 2008 froze global credit.","zh-TW":"二○○八年結構性金融市場的崩潰凍結了全球信貸。"}]', NULL, NULL, 5, 6274, NULL),
(6275, 'structured learning', '/''strʌktʃərd ˌlɜːrnɪŋ/', 'noun', '{"zh-TW":["結構化學習；有組織的學習"],"en":["a planned and systematic approach to education with defined goals and methods"]}', NULL, 'benefit from structured learning / structured learning environment / structured learning plan', '[{"en":"Structured learning programs provide clear goals, materials, and progress metrics.","zh-TW":"結構化學習計劃提供明確的目標、材料和進度指標。"},{"en":"Children with learning differences often benefit from structured learning environments.","zh-TW":"有學習差異的兒童往往受益於結構化學習環境。"}]', NULL, NULL, 5, 6275, NULL),
(6276, 'stubborn', '/ˈstʌbərn/', 'adjective', '{"zh-TW":["固執的"],"en":["refusing to change one''s mind"]}', '{"root":{"text":"stub","meaning":"stump (樹樁)"},"logic":"如同樹樁般不動搖的，即「固執的」。"}', 'stubborn refusal / stubborn as a mule', '[{"en":"He is too stubborn to ask for help.","zh-TW":"他太固執不肯求助。"},{"en":"Her stubborn refusal caused problems.","zh-TW":"她固執的拒絕造成了問題。"}]', '{"noun":"stubbornness","adverb":"stubbornly"}', NULL, 3, 6276, NULL),
(6277, 'student', '/ˈstjuːdənt/', 'noun', '{"zh-TW":["學生"],"en":["a person who is studying"]}', NULL, 'student loan / exchange student', '[{"en":"Student loans are a heavy burden.","zh-TW":"學生貸款是沉重的負擔。"},{"en":"We hire exchange students as interns.","zh-TW":"我們聘請交換學生當實習生。"}]', '{"noun":"student","noun2":"study","verb":"study"}', NULL, 3, 6277, NULL),
(6278, 'student loan', '/ˈstjuːdənt ləʊn/', 'noun', '{"zh-TW":["學生貸款"],"en":["money borrowed to pay for education expenses"]}', NULL, 'apply for a student loan / repay a student loan', '[{"en":"Student loans must be repaid after graduation.","zh-TW":"學生貸款必須在畢業後償還。"},{"en":"Many students rely on student loans to fund their education.","zh-TW":"許多學生依靠學生貸款資助他們的教育。"}]', NULL, NULL, 4, 6278, NULL),
(6279, 'student union', '/''stjuːdənt ˌjuːniən/', 'noun', '{"zh-TW":["學生會；學生聯合會"],"en":["an organization representing the interests of students at a college or university"]}', NULL, 'join the student union / student union election / student union representative', '[{"en":"The student union organized several events to welcome new students to campus.","zh-TW":"學生會組織了幾個活動，歡迎新生入學。"},{"en":"She ran for president of the student union in her second year.","zh-TW":"她在第二年競選學生會主席。"}]', NULL, NULL, 5, 6279, NULL),
(6280, 'studio', '/ˈstjuːdioʊ/', 'noun', '{"zh-TW":["工作室；錄音室"],"en":["a room where an artist or musician works"]}', '{"root":{"text":"studi","meaning":"study/devote (研究/投入)"},"suffix":{"text":"-o","meaning":"place (場所)"},"logic":"投入研究創作的場所，即「工作室」。"}', 'art studio / recording studio / studio apartment', '[{"en":"The photographer works in her studio.","zh-TW":"攝影師在她的工作室工作。"},{"en":"The band recorded the album in a professional studio.","zh-TW":"樂團在專業錄音室錄製了這張專輯。"}]', NULL, NULL, 2, 6280, NULL),
(6281, 'study', '/ˈstʌdi/', 'verb', '{"zh-TW":["學習；研究"],"en":["to learn about a subject","to examine carefully"]}', NULL, 'case study / feasibility study', '[{"en":"We conducted a feasibility study.","zh-TW":"我們進行了可行性研究。"},{"en":"This case study shows best practices.","zh-TW":"這個案例研究展示了最佳實踐。"}]', '{"verb":"study","noun":"study","noun2":"student"}', NULL, 2, 6281, NULL),
(6282, 'study abroad', '/ˈstʌdi əˈbrɔːd/', 'noun', '{"zh-TW":["海外留學"],"en":["studying at an educational institution in another country"]}', NULL, 'study abroad program / apply to study abroad', '[{"en":"He spent one year in Germany as part of his study abroad program.","zh-TW":"他作為海外留學計劃的一部分在德國待了一年。"},{"en":"Study abroad experiences enhance cross-cultural understanding.","zh-TW":"海外留學經驗增強了跨文化理解。"}]', NULL, NULL, 4, 6282, NULL),
(6283, 'study group', '/''stʌdi ɡruːp/', 'noun', '{"zh-TW":["學習小組；讀書會"],"en":["a group of students who meet regularly to study together and help each other understand material"]}', NULL, 'form a study group / join a study group / benefit of study group', '[{"en":"She formed a study group with classmates to prepare for the final examination.","zh-TW":"她和同學組成了學習小組，為期末考試做準備。"},{"en":"A study group can help members tackle difficult topics more effectively.","zh-TW":"學習小組可以幫助成員更有效地處理困難的主題。"}]', NULL, NULL, 4, 6283, NULL),
(6284, 'style', 'staɪl', 'noun', '{"zh-TW":["風格；方式","樣式"],"en":["a way of doing something","a particular design"]}', NULL, 'work style/management style', '[{"en":"Her management style is collaborative.","zh-TW":"她的管理風格是協作式的。"}]', '{"verb":"style","adjective":"stylish","adverb":"stylishly"}', NULL, 2, 6284, NULL),
(6285, 'subagent', '/ˈsʌbeɪdʒənt/', 'noun', '{"zh-TW":["次代理；子代理人"],"en":["an agent authorized by another agent to perform certain duties"]}', NULL, 'appoint a subagent / subagent agreement', '[{"en":"The broker appointed a local subagent in each city.","zh-TW":"經紀人在每個城市任命了一名本地次代理。"},{"en":"The subagent is authorized to sign documents on behalf of the main agent.","zh-TW":"次代理有權代表主要代理人簽署文件。"}]', NULL, NULL, 3, 6285, NULL),
(6286, 'subcontract', '/ˌsʌbkənˈtrækt/', 'verb, noun', '{"zh-TW":["分包；轉包","分包合約"],"en":["to hire another company to do part of the work"]}', NULL, 'subcontract work / subcontract to / subcontractor', '[{"en":"The firm subcontracted the IT work to a specialist.","zh-TW":"公司將IT工作分包給專業人員。"},{"en":"We use subcontractors for maintenance services.","zh-TW":"我們使用分包商提供維護服務。"}]', '{"noun":"subcontract, subcontractor","verb":"subcontract"}', NULL, 4, 6286, NULL),
(6287, 'subcontractor', '/ˌsʌbkənˈtræktər/', 'noun', '{"zh-TW":["分包商；次承包商"],"en":["a company hired by the main contractor to complete specific work"]}', NULL, 'hire a subcontractor / subcontractor agreement', '[{"en":"The builder hired a subcontractor to install the electrical systems.","zh-TW":"建築商聘請了分包商安裝電力系統。"},{"en":"Subcontractor performance affects the main project timeline.","zh-TW":"分包商的表現影響著主項目的時間表。"}]', '{"verb":"subcontract","adjective":"subcontracted"}', NULL, 5, 6287, NULL),
(6288, 'subject', '/ˈsʌbdʒɪkt/', 'noun, adjective, verb', '{"zh-TW":["主題；科目","受...支配的","使遭受"],"en":["a topic; a branch of study","dependent on","to cause to experience"]}', NULL, 'subject to / on the subject of / subject matter', '[{"en":"The plan is subject to board approval.","zh-TW":"該計畫需經董事會批准。"},{"en":"Let''s not change the subject.","zh-TW":"我們不要改變話題。"}]', '{"noun":"subject","verb":"subject","adjective":"subject, subjective"}', NULL, 3, 6288, 463),
(6289, 'subjectivity', '/ˌsʌbdʒekˈtɪvɪti/', 'noun', '{"zh-TW":["主觀性"],"en":["the quality of being based on personal feelings, opinions, or experience"]}', NULL, 'overcome subjectivity / acknowledge subjectivity / reduce subjectivity', '[{"en":"Qualitative research involves inherent subjectivity that must be acknowledged.","zh-TW":"質性研究涉及必須承認的固有主觀性。"},{"en":"Performance reviews can be influenced by the subjectivity of the evaluator.","zh-TW":"績效評估可能受到評估者主觀性的影響。"}]', '{"adjective":"subjective","adverb":"subjectively"}', NULL, 4, 6289, NULL),
(6290, 'sublease', '/ˈsʌbliːs/', 'noun', '{"zh-TW":["轉租；分租"],"en":["renting property that you have leased from another party"]}', NULL, 'sublease agreement / enter a sublease / sublease the office', '[{"en":"The company subleased part of its office space to a startup.","zh-TW":"公司將部分辦公空間轉租給一家新創公司。"},{"en":"The sublease required approval from the original landlord.","zh-TW":"轉租需要原房東的批准。"}]', '{"verb":"sublease","noun":"sublessee"}', NULL, 3, 6290, NULL),
(6291, 'subletting', '/''sʌbˌletɪŋ/', 'noun', '{"zh-TW":["轉租；分租"],"en":["the practice of renting all or part of a property that you are already renting to another person"]}', NULL, 'allow subletting / prohibit subletting / subletting arrangement', '[{"en":"The lease agreement prohibited subletting without the landlord''s written consent.","zh-TW":"租賃協議禁止未經房東書面同意進行轉租。"},{"en":"She arranged subletting for the months she was abroad to help cover the rent.","zh-TW":"她安排了在海外幾個月的轉租，以幫助支付租金。"}]', '{"verb":"sublet"}', NULL, 4, 6291, NULL),
(6292, 'submission', 'səbˈmɪʃən', 'noun', '{"zh-TW":["提交；呈遞","服從"],"en":["the act of presenting formally","a document submitted"]}', NULL, 'on-time submission/final submission', '[{"en":"Please ensure on-time submission.","zh-TW":"請確保按時提交。"}]', '{"verb":"submit","adjective":"submitted"}', NULL, 4, 6292, 624),
(6293, 'submit', '/səbˈmɪt/', 'verb', '{"zh-TW":["提交；呈交","服從"],"en":["to present for consideration","to yield to authority"]}', '{"prefix":{"text":"sub-","meaning":"在...之下"},"root":{"text":"mit","meaning":"send (發送)"}}', 'submit a report / submit an application / submit a proposal', '[{"en":"Please submit your application by Friday.","zh-TW":"請在週五前提交您的申請。"},{"en":"All expenses must be submitted for approval.","zh-TW":"所有費用都必須提交審批。"}]', '{"noun":"submission","verb":"submit"}', NULL, 2, 6293, 62),
(6294, 'subordinate', '/səˈbɔːrdɪnət/', 'noun, adjective', '{"zh-TW":["下屬；部屬","次要的；從屬的"],"en":["a person under the authority of another","lower in rank"]}', NULL, 'subordinate to / direct subordinate', '[{"en":"Managers should support their subordinates.","zh-TW":"經理應該支持他們的下屬。"},{"en":"Personal interests are subordinate to company goals.","zh-TW":"個人利益從屬於公司目標。"}]', '{"noun":"subordinate, subordination","adjective":"subordinate","verb":"subordinate"}', NULL, 4, 6294, 937),
(6295, 'subpoena', '/səˈpiːnə/', 'noun', '{"zh-TW":["傳票；傳喚"],"en":["a legal document ordering someone to appear in court or produce evidence"]}', NULL, 'issue a subpoena / comply with a subpoena / receive a subpoena', '[{"en":"The court issued a subpoena requiring the executive to testify.","zh-TW":"法院發出傳票要求高管出庭作證。"},{"en":"Failure to comply with a subpoena can result in contempt of court.","zh-TW":"不遵守傳票可能導致藐視法庭。"}]', '{"verb":"subpoena"}', NULL, 3, 6295, NULL),
(6296, 'subprime', '/ˈsʌbˌpraɪm/', 'adjective', '{"zh-TW":["次級的；低於優質級的"],"en":["denoting loans or borrowers that don''t meet standard criteria for creditworthiness"]}', NULL, 'subprime mortgage / subprime lending / subprime market', '[{"en":"The collapse of the subprime mortgage market triggered the 2008 financial crisis.","zh-TW":"次級抵押貸款市場的崩潰引發了二○○八年的金融危機。"},{"en":"Subprime lending practices exposed banks to higher default risks.","zh-TW":"次級貸款做法使銀行面臨更高的違約風險。"}]', NULL, NULL, 3, 6296, NULL),
(6297, 'subscribe', '/səbˈskraɪb/', 'verb', '{"zh-TW":["訂閱；認購","同意"],"en":["to pay regularly for a service","to agree with an idea"]}', NULL, 'subscribe to / subscription service / subscribe to a newsletter', '[{"en":"Over 10,000 users subscribe to our newsletter.","zh-TW":"超過一萬名用戶訂閱我們的電子報。"},{"en":"I don''t subscribe to that theory.","zh-TW":"我不認同那個理論。"}]', '{"noun":"subscription, subscriber","verb":"subscribe"}', NULL, 3, 6297, NULL),
(6298, 'subscription', '/səbˈskrɪpʃən/', 'noun', '{"zh-TW":["訂閱；訂閱制"],"en":["a model where customers pay regularly for ongoing access to a product"]}', NULL, 'subscription model / subscription fee / annual subscription / cancel subscription', '[{"en":"The company switched to a subscription model for stable recurring revenue.","zh-TW":"公司轉向訂閱模式以獲得穩定的經常性收入。"},{"en":"Monthly subscriptions increased by 40% after the price reduction.","zh-TW":"降價後，月度訂閱數量增加了40%。"}]', '{"verb":"subscribe","noun":"subscriber"}', NULL, 4, 6298, NULL),
(6299, 'subscription fee', '/səbˈskrɪpʃən fiː/', 'noun', '{"zh-TW":["訂閱費；會員費"],"en":["a recurring charge paid for ongoing access to a service"]}', NULL, 'charge a subscription fee / monthly subscription fee', '[{"en":"The platform charges a monthly subscription fee of 15 dollars.","zh-TW":"平台收取每月15美元的訂閱費。"},{"en":"The subscription fee was reduced for annual payment plans.","zh-TW":"年度付款計劃的訂閱費降低了。"}]', NULL, NULL, 5, 6299, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6300, 'subscription model', '/səbˈskrɪpʃən ˈmɒdəl/', 'noun', '{"zh-TW":["訂閱模式"],"en":["a business model where customers pay regularly for ongoing access"]}', NULL, 'adopt a subscription model / subscription model revenue', '[{"en":"The software company moved to a subscription model for recurring revenue.","zh-TW":"軟體公司轉向了訂閱模式以獲得經常性收入。"},{"en":"A subscription model improves revenue predictability.","zh-TW":"訂閱模式提高了收入的可預測性。"}]', NULL, NULL, 5, 6300, NULL),
(6301, 'subsequent', '/ˈsʌbsɪkwənt/', 'adjective', '{"zh-TW":["隨後的；後續的"],"en":["coming after something in time"]}', NULL, 'subsequent to / subsequent events / in subsequent years', '[{"en":"Subsequent meetings will address remaining issues.","zh-TW":"後續會議將處理剩餘問題。"},{"en":"Sales improved in subsequent quarters.","zh-TW":"銷售額在接下來的幾季有所改善。"}]', '{"adjective":"subsequent","adverb":"subsequently"}', NULL, 4, 6301, NULL),
(6302, 'subsidiary', '/səbˈsɪdieri/', 'noun, adjective', '{"zh-TW":["子公司","附屬的；次要的"],"en":["a company controlled by another company","less important"]}', NULL, 'wholly-owned subsidiary / subsidiary company', '[{"en":"The company has subsidiaries in 20 countries.","zh-TW":"該公司在20個國家設有子公司。"},{"en":"This is a wholly-owned subsidiary of the group.","zh-TW":"這是集團的全資子公司。"}]', '{"noun":"subsidiary"}', NULL, 4, 6302, NULL),
(6303, 'subsidiary company', '/səbˈsɪdiəri ˈkʌmpəni/', 'noun', '{"zh-TW":["子公司"],"en":["a company controlled by a parent or holding company"]}', NULL, 'wholly-owned subsidiary / establish a subsidiary company', '[{"en":"The subsidiary company operates independently in the Asian market.","zh-TW":"子公司在亞洲市場獨立運營。"},{"en":"Revenue from the subsidiary company contributed 20% to group earnings.","zh-TW":"子公司的收入貢獻了集團盈利的20%。"}]', '{"plural":"subsidiary companies"}', NULL, 5, 6303, NULL),
(6304, 'subsidiary rights', '/səbˈsɪdiəri raɪts/', 'noun', '{"zh-TW":["附屬權利；衍生版權"],"en":["secondary rights derived from a primary work, such as foreign language or film rights"]}', NULL, 'license subsidiary rights / subsidiary rights agreement', '[{"en":"The publisher sold subsidiary rights for translation into 12 languages.","zh-TW":"出版商出售了翻譯成12種語言的附屬版權。"},{"en":"Subsidiary rights generate additional revenue beyond the primary publication.","zh-TW":"附屬版權在主要出版物之外產生了額外收入。"}]', NULL, NULL, 5, 6304, NULL),
(6305, 'subsidy', '/ˈsʌbsɪdi/', 'noun', '{"zh-TW":["補貼；補助金"],"en":["money granted by the government to assist an industry"]}', NULL, 'government subsidy / subsidy program', '[{"en":"The government provides subsidies for electric vehicle purchases.","zh-TW":"政府為購買電動車提供補貼。"},{"en":"Subsidies for renewable energy have driven its rapid expansion.","zh-TW":"對可再生能源的補貼推動了其快速擴展。"}]', '{"verb":"subsidize","adjective":"subsidized"}', NULL, 3, 6305, NULL),
(6306, 'substance', '/ˈsʌbstəns/', 'noun', '{"zh-TW":["物質；實質","要旨"],"en":["a type of matter","the real content or meaning"]}', NULL, 'chemical substance / in substance / substance abuse', '[{"en":"The report lacks substance.","zh-TW":"這份報告缺乏實質內容。"},{"en":"Hazardous substances must be handled carefully.","zh-TW":"危險物質必須小心處理。"}]', '{"noun":"substance","adjective":"substantial, substantive"}', NULL, 3, 6306, NULL),
(6307, 'substandard', '/ˌsʌbˈstændərd/', 'adjective', '{"zh-TW":["低於標準的；不合格的"],"en":["below the required or expected quality"]}', NULL, 'substandard goods / substandard work / substandard quality', '[{"en":"The supplier delivered substandard components that failed quality checks.","zh-TW":"供應商交付了未能通過品質檢查的不合格零件。"},{"en":"Substandard work will not be accepted by the client.","zh-TW":"客戶不會接受不合格的工作。"}]', '{"adverb":"substandard"}', NULL, 4, 6307, NULL),
(6308, 'substantial', '/səbˈstænʃl/', 'adjective', '{"zh-TW":["大量的；可觀的","實質的"],"en":["of considerable importance or size"]}', NULL, 'substantial amount / substantial improvement / substantial evidence', '[{"en":"We made a substantial investment in technology.","zh-TW":"我們在技術方面進行了大量投資。"},{"en":"There has been substantial improvement in quality.","zh-TW":"品質有了顯著的改善。"}]', '{"noun":"substance","adjective":"substantial","adverb":"substantially"}', NULL, 4, 6308, NULL),
(6309, 'substantially', '/''səbˈstænʃəli/', 'adverb', '{"zh-TW":["大幅地；顯著地"],"en":["to a great or significant extent; considerably"]}', NULL, 'substantially different / substantially improved / substantially increased', '[{"en":"The new policy substantially reduced administrative overhead.","zh-TW":"新政策大幅降低了行政費用。"},{"en":"Her performance substantially improved after she received targeted coaching.","zh-TW":"在獲得有針對性的指導後，她的表現顯著改善。"}]', '{"adjective":"substantial"}', NULL, 5, 6309, NULL),
(6310, 'substantiate', '/səbˈstænʃieɪt/', 'verb', '{"zh-TW":["證實；提供實質依據"],"en":["to provide evidence to support or prove the truth of something"]}', NULL, 'substantiate a claim / substantiate findings / substantiate evidence', '[{"en":"The data substantiate the researcher''s central claim.","zh-TW":"數據證實了研究員的核心主張。"},{"en":"You need concrete examples to substantiate your argument.","zh-TW":"你需要具體例子來為你的論點提供依據。"}]', '{"noun":"substantiation","adjective":"substantiated"}', NULL, 4, 6310, NULL),
(6311, 'substitute', '/ˈsʌbstɪtuːt/', 'noun, verb', '{"zh-TW":["替代品；代替者","替代；取代"],"en":["a person or thing acting in place of another","to use instead of"]}', NULL, 'substitute for / substitute teacher / no substitute for', '[{"en":"There is no substitute for hard work.","zh-TW":"勤奮是無可替代的。"},{"en":"You can substitute olive oil for butter.","zh-TW":"你可以用橄欖油代替奶油。"}]', '{"noun":"substitute, substitution","verb":"substitute"}', NULL, 4, 6311, NULL),
(6312, 'subtext', '/ˈsʌbtekst/', 'noun', '{"zh-TW":["潛台詞；言外之意"],"en":["the underlying theme in a piece of writing or conversation"]}', NULL, 'read the subtext / rich subtext / political subtext', '[{"en":"The dialogue has a powerful subtext about class and ambition.","zh-TW":"這段對話有一個關於階層和野心的深刻潛台詞。"},{"en":"Great acting requires understanding and conveying the subtext.","zh-TW":"出色的表演需要理解並傳達潛台詞。"}]', NULL, NULL, 3, 6312, NULL),
(6313, 'subtle', '/ˈsʌtl/', 'adjective', '{"zh-TW":["微妙的；細微的"],"en":["not immediately obvious; delicate"]}', NULL, 'subtle difference / subtle change / subtle hint', '[{"en":"There is a subtle difference between the two products.","zh-TW":"這兩款產品之間有微妙的差異。"},{"en":"She made a subtle hint about the promotion.","zh-TW":"她暗示了關於升遷的事。"}]', '{"noun":"subtlety","adjective":"subtle","adverb":"subtly"}', NULL, 2, 6313, NULL),
(6314, 'suburb', '/''sʌbɜːrb/', 'noun', '{"zh-TW":["郊區；郊外"],"en":["a residential area on the outskirts of a city or large town"]}', NULL, 'quiet suburb / suburban area / move to the suburbs', '[{"en":"Many families prefer the suburbs for their lower cost of living and safer environment.","zh-TW":"許多家庭偏好郊區，因為那裡生活費用較低且環境更安全。"},{"en":"The suburb was originally a small farming community but grew rapidly after urban expansion.","zh-TW":"郊區最初是一個小農業社區，但在城市擴張後迅速發展。"}]', '{"adjective":"suburban","noun":"suburbia"}', NULL, 2, 6314, NULL),
(6315, 'succeed', '/səkˈsiːd/', 'verb', '{"zh-TW":["成功；繼任"],"en":["to achieve a goal; to come after"]}', NULL, 'succeed in / succeed as / succeed someone', '[{"en":"The company succeeded in entering the Asian market.","zh-TW":"公司成功進入了亞洲市場。"},{"en":"She succeeded him as CEO.","zh-TW":"她接替他擔任執行長。"}]', '{"noun":"success, succession, successor","verb":"succeed","adjective":"successful, successive"}', NULL, 3, 6315, NULL),
(6316, 'success', 'səkˈsɛs', 'noun', '{"zh-TW":["成功；成就","好結果"],"en":["the achievement of a goal","a favorable outcome"]}', NULL, 'business success/measure of success', '[{"en":"Success depends on teamwork.","zh-TW":"成功取決於團隊合作。"}]', '{"verb":"succeed","adjective":"successful","adverb":"successfully"}', NULL, 3, 6316, NULL),
(6317, 'successful', 'səkˈsɛsfəl', 'adjective', '{"zh-TW":["成功的；有成就的","出色的"],"en":["having achieved a desired goal","prosperous"]}', NULL, 'successful project/successful launch', '[{"en":"The product launch was very successful.","zh-TW":"產品發布非常成功。"}]', '{"noun":"success","adverb":"successfully"}', NULL, 4, 6317, 224),
(6318, 'succession', '/səkˈseʃən/', 'noun', '{"zh-TW":["接替；繼承"],"en":["the process of one person taking over another''s role or position"]}', NULL, 'succession plan / succession of management / leadership succession', '[{"en":"Smooth succession is critical to maintaining business continuity.","zh-TW":"順暢的繼任對維持業務連續性至關重要。"},{"en":"The board developed a succession strategy for the retiring CFO.","zh-TW":"董事會為即將退休的財務長制定了繼任策略。"}]', '{"verb":"succeed","noun":"successor"}', NULL, 4, 6318, 938),
(6319, 'succession planning', '/səkˈseʃən ˈplænɪŋ/', 'noun', '{"zh-TW":["接班規劃；接任計劃"],"en":["preparing for future leadership transitions within an organization"]}', NULL, 'succession planning process / executive succession planning', '[{"en":"Succession planning ensures leadership continuity during transitions.","zh-TW":"接班規劃確保過渡期間的領導層連續性。"},{"en":"The board emphasized succession planning after the CEO retired.","zh-TW":"執行長退休後，董事會強調了接班規劃的重要性。"}]', '{"verb":"plan succession"}', NULL, 5, 6319, NULL),
(6320, 'succinct', '/səkˈsɪŋkt/', 'adjective', '{"zh-TW":["簡潔的；精練的"],"en":["briefly and clearly expressed"]}', NULL, 'succinct summary / succinct explanation / succinct response', '[{"en":"A succinct abstract conveys the key points of the research.","zh-TW":"簡潔的摘要傳達研究的關鍵點。"},{"en":"He gave a succinct answer that satisfied all the reviewers.","zh-TW":"他給出了一個簡潔的答案，讓所有評審都感到滿意。"}]', '{"adverb":"succinctly","noun":"succinctness"}', NULL, 3, 6320, NULL),
(6321, 'sufficient', '/səˈfɪʃnt/', 'adjective', '{"zh-TW":["足夠的","足夠的；充分的"],"en":["enough to meet the needs"]}', '{"prefix":{"text":"suf-","meaning":"under/up (從下)"},"root":{"text":"fic","meaning":"make/do (做)"},"suffix":{"text":"-ient","meaning":"being (…的)"},"logic":"做到位的，即「足夠的」。"}', 'sufficient evidence / sufficient time / self-sufficient; sufficient funds / sufficient evidence / self-sufficient', '[{"en":"Do we have sufficient time to finish?","zh-TW":"我們有足夠的時間完成嗎？"},{"en":"The evidence is not sufficient to prove guilt.","zh-TW":"證據不足以證明有罪。"},{"en":"We have sufficient funds to complete the project.","zh-TW":"我們有足夠的資金完成這個專案。"},{"en":"The evidence is not sufficient to prove the claim.","zh-TW":"證據不足以證明該主張。"}]', '{"noun":"sufficiency","adverb":"sufficiently","adjective":"sufficient, insufficient"}', NULL, 4, 6321, NULL),
(6322, 'suggest', '/səˈdʒest/', 'verb', '{"zh-TW":["建議；暗示"],"en":["to put forward an idea; to indicate"]}', NULL, 'suggest that / strongly suggest / suggest an alternative', '[{"en":"I suggest we postpone the meeting.","zh-TW":"我建議我們延後會議。"},{"en":"The data suggests a positive trend.","zh-TW":"數據暗示了一個正面的趨勢。"}]', '{"noun":"suggestion","verb":"suggest","adjective":"suggestive"}', NULL, 3, 6322, NULL),
(6323, 'suit', '/suːt/', 'noun, verb', '{"zh-TW":["【主要意義-名詞】西裝；套裝","【次要意義-動詞】適合；對……合適","【次要意義-名詞】訴訟；法律行動","【次要意義-名詞】（撲克牌）花色"],"en":["[primary - noun] a set of matching clothes","[secondary - verb] to be convenient or appropriate for someone","[secondary - noun] a legal case or proceeding","[secondary - noun] one of the four sets of cards in a deck"]}', NULL, 'suit someone / file a suit / follow suit / a lawsuit / strong suit', '[{"en":"The new office hours suit most employees very well.","zh-TW":"新的辦公時間非常適合大多數員工。"},{"en":"The company filed a suit against its former partner for breach of contract.","zh-TW":"公司就違約問題對前合作夥伴提起了訴訟。"},{"en":"When the market leader lowered prices, competitors followed suit.","zh-TW":"當市場領導者降價時，競爭者也紛紛效仿。"}]', '{"adjective":"suitable, unsuitable","noun":"suitability"}', '動詞 suit = 「適合」，名詞 suit = 「訴訟」（lawsuit），片語 follow suit = 「效仿/跟進」，TOEIC 法律和商業文章的高頻詞彙。', 1, 6323, NULL),
(6324, 'suitable', 'ˈsuːtəbəl', 'adjective', '{"zh-TW":["合適的；適宜的","相稱的"],"en":["right for a particular purpose","appropriate"]}', NULL, 'suitable candidate/suitable time', '[{"en":"Is Monday a suitable time for the meeting?","zh-TW":"週一是開會的合適時間嗎？"}]', '{"noun":"suitability","adverb":"suitably"}', NULL, 3, 6324, NULL),
(6325, 'suite', '/swiːt/', 'noun', '{"zh-TW":["套房"],"en":["a set of connected rooms in a hotel"]}', NULL, 'luxury suite / book a suite', '[{"en":"They booked a suite for their honeymoon.","zh-TW":"他們為蜜月預訂了套房。"},{"en":"The suite includes a living room and a bedroom.","zh-TW":"套房包含客廳和臥室。"}]', NULL, NULL, 2, 6325, NULL),
(6326, 'summarize', '/ˈsʌməraɪz/', 'verb', '{"zh-TW":["總結；概述"],"en":["to give a brief statement of the main points"]}', NULL, 'summarize the findings / to summarize / briefly summarize', '[{"en":"Please summarize the key findings of the report.","zh-TW":"請總結報告的主要發現。"},{"en":"To summarize, we need to reduce costs by 15%.","zh-TW":"總結來說，我們需要降低15%的成本。"}]', '{"noun":"summary","verb":"summarize"}', NULL, 3, 6326, NULL),
(6327, 'summary', 'ˈsʌməri', 'noun', '{"zh-TW":["摘要；總結","概要"],"en":["a brief statement of main points","an overview"]}', NULL, 'executive summary/provide a summary', '[{"en":"Please provide a summary of the report.","zh-TW":"請提供報告的摘要。"}]', '{"verb":"summarize","adjective":"summary"}', NULL, 3, 6327, 464),
(6328, 'summative assessment', '/''sʌmətɪv əˌsesmənt/', 'noun', '{"zh-TW":["總結性評估；終結性評量"],"en":["evaluation of student learning at the end of an instructional period against a standard or benchmark"]}', NULL, 'summative assessment result / summative assessment design / use summative assessment', '[{"en":"Final exams and standardized tests are common forms of summative assessment.","zh-TW":"期末考試和標準化測驗是常見的總結性評估形式。"},{"en":"Summative assessment measures whether students have achieved the learning objectives.","zh-TW":"總結性評估衡量學生是否達到了學習目標。"}]', '{"adjective":"summative"}', NULL, 5, 6328, NULL),
(6329, 'summit', '/ˈsʌmɪt/', 'noun', '{"zh-TW":["高峰會；峰會","頂點"],"en":["a meeting between heads of government","the highest point"]}', NULL, 'economic summit / summit meeting / reach the summit', '[{"en":"Leaders gathered for the G20 summit.","zh-TW":"領袖們齊聚G20高峰會。"},{"en":"The summit addressed climate change issues.","zh-TW":"峰會討論了氣候變遷議題。"}]', '{"noun":"summit"}', NULL, 2, 6329, NULL),
(6330, 'sunk cost', '/sʌŋk kɒst/', 'noun', '{"zh-TW":["沉沒成本"],"en":["a cost that has already been incurred and cannot be recovered"]}', NULL, 'ignore sunk costs / sunk cost fallacy', '[{"en":"Managers should not let sunk costs influence future decisions.","zh-TW":"管理者不應讓沉沒成本影響未來的決策。"},{"en":"The project was cancelled despite the sunk cost of $2 million already spent.","zh-TW":"儘管已投入200萬元的沉沒成本，該項目仍被取消了。"}]', NULL, NULL, 3, 6330, NULL),
(6331, 'superficial', '/''suːpərˈfɪʃəl/', 'adjective', '{"zh-TW":["表面的；膚淺的"],"en":["existing or occurring at or on the surface; not thorough or deep; lacking depth"]}', NULL, 'superficial understanding / superficial analysis / superficial impression', '[{"en":"A superficial analysis of the data missed the underlying trends.","zh-TW":"對數據的表面分析遺漏了潛在趨勢。"},{"en":"Their business relationship remained superficial and never developed into a true partnership.","zh-TW":"他們的商業關係保持表面，從未發展成真正的合夥關係。"}]', '{"adverb":"superficially","noun":"superficiality"}', NULL, 4, 6331, NULL),
(6332, 'superfluous', '/''suːˈpɜːrfluəs/', 'adjective', '{"zh-TW":["多餘的；過剩的"],"en":["unnecessary, especially through being more than enough"]}', NULL, 'superfluous information / superfluous details / superfluous steps', '[{"en":"The editor removed several superfluous paragraphs to tighten the article.","zh-TW":"編輯刪除了幾個多餘的段落，使文章更精煉。"},{"en":"Superfluous meetings consume time that could be spent on productive work.","zh-TW":"多餘的會議消耗了本可用於生產性工作的時間。"}]', '{"adverb":"superfluously","noun":"superfluousness"}', NULL, 4, 6332, NULL),
(6333, 'superfood', '/''suːpərˌfuːd/', 'noun', '{"zh-TW":["超級食物"],"en":["a nutrient-rich food considered to be especially beneficial for health and well-being"]}', NULL, 'eat superfoods / superfood smoothie / popular superfood', '[{"en":"Quinoa, chia seeds, and kale are often cited as superfoods.","zh-TW":"藜麥、奇亞籽和羽衣甘藍常被列為超級食物。"},{"en":"The superfood trend has driven demand for ingredients like acai and spirulina.","zh-TW":"超級食物趨勢推動了對巴西莓和螺旋藻等食材的需求。"}]', NULL, NULL, 3, 6333, NULL),
(6334, 'supersede', '/''suːpərˌsiːd/', 'verb', '{"zh-TW":["取代；替代"],"en":["to take the place of something previously in use or accepted; to replace"]}', NULL, 'supersede a rule / supersede a technology / be superseded by', '[{"en":"The new regulation superseded the previous rules that had been in place for decades.","zh-TW":"新法規取代了已實施數十年的舊規定。"},{"en":"Digital music services have largely superseded physical CD sales.","zh-TW":"數字音樂服務在很大程度上已取代了實體CD銷售。"}]', '{"noun":"supersession","adjective":"superseding"}', NULL, 3, 6334, NULL),
(6335, 'supervise', '/ˈsuːpərvaɪz/', 'verb', '{"zh-TW":["監督；管理"],"en":["to oversee the work of others"]}', NULL, 'supervise employees / supervise a project / closely supervised', '[{"en":"She supervises a team of 15 engineers.","zh-TW":"她管理一個15人的工程師團隊。"},{"en":"The construction work is closely supervised.","zh-TW":"施工工程受到密切監督。"}]', '{"noun":"supervision, supervisor","verb":"supervise","adjective":"supervisory"}', NULL, 3, 6335, NULL),
(6336, 'supervisor', '/ˈsuːpərvaɪzər/', 'noun', '{"zh-TW":["主管；監督者"],"en":["a person who oversees the work of other employees"]}', NULL, 'direct supervisor / report to a supervisor / supervisory role', '[{"en":"He reported any issues directly to his supervisor.","zh-TW":"他直接向主管報告任何問題。"},{"en":"The supervisor provided daily guidance to the team.","zh-TW":"主管每天向團隊提供指導。"}]', '{"plural":"supervisors","verb":"supervise","adjective":"supervisory"}', NULL, 4, 6336, NULL),
(6337, 'supplement', '/ˈsʌplɪmənt/', 'noun, verb', '{"zh-TW":["補充；補充物","補充"],"en":["something added to complete","to add to something"]}', NULL, 'supplement income / dietary supplement / supplement with', '[{"en":"Many freelancers supplement their income with part-time work.","zh-TW":"許多自由工作者用兼職來補充收入。"},{"en":"The report is supplemented with charts.","zh-TW":"報告附有圖表作為補充。"}]', '{"noun":"supplement","verb":"supplement","adjective":"supplementary"}', NULL, 4, 6337, 724),
(6338, 'supplier', '/səˈplaɪər/', 'noun', '{"zh-TW":["供應商"],"en":["a company that provides goods or services to another business"]}', NULL, 'key supplier / supplier relationship / preferred supplier / supplier evaluation', '[{"en":"The company maintains long-term relationships with key suppliers.","zh-TW":"公司與關鍵供應商保持長期關係。"},{"en":"A supplier audit was conducted to verify quality standards.","zh-TW":"進行了供應商審計以驗證品質標準。"}]', '{"plural":"suppliers","verb":"supply"}', NULL, 3, 6338, NULL),
(6339, 'supplier audit', '/səˈplaɪər ˈɔːdɪt/', 'noun', '{"zh-TW":["供應商審計"],"en":["a formal inspection of a supplier operations, quality, and compliance"]}', NULL, 'conduct a supplier audit / annual supplier audit', '[{"en":"The procurement team conducted surprise supplier audits twice a year.","zh-TW":"採購團隊每年進行兩次突擊供應商審計。"},{"en":"A supplier audit revealed substandard conditions in the factory.","zh-TW":"供應商審計揭示了工廠中低於標準的條件。"}]', NULL, NULL, 5, 6339, NULL),
(6340, 'supplier evaluation', '/səˈplaɪər ɪˌvæljuˈeɪʃən/', 'noun', '{"zh-TW":["供應商評估"],"en":["a review of a supplier''s performance and reliability"]}', NULL, 'conduct supplier evaluation / supplier evaluation criteria', '[{"en":"Annual supplier evaluations help identify the best partners.","zh-TW":"年度供應商評估幫助識別最佳合作夥伴。"},{"en":"The procurement team uses a scorecard for supplier evaluation.","zh-TW":"採購團隊使用評分卡進行供應商評估。"}]', NULL, NULL, 5, 6340, NULL),
(6341, 'supply', '/səˈplaɪ/', 'noun, verb', '{"zh-TW":["供應；供給","供應；提供"],"en":["an amount available for use","to provide what is needed"]}', NULL, 'supply and demand / supply chain / supply shortage', '[{"en":"The supply chain was disrupted by the pandemic.","zh-TW":"供應鏈受到疫情的影響而中斷。"},{"en":"The company supplies parts to major automakers.","zh-TW":"這家公司為主要汽車製造商供應零件。"}]', '{"noun":"supply, supplier","verb":"supply"}', NULL, 2, 6341, 63),
(6342, 'supply agreement', '/səˈplaɪ əˈɡriːmənt/', 'noun', '{"zh-TW":["供應協議"],"en":["a contract between a supplier and buyer specifying terms for supply of goods"]}', NULL, 'sign a supply agreement / supply agreement terms', '[{"en":"A three-year supply agreement was signed to ensure pricing stability.","zh-TW":"簽署了三年供應協議以確保定價穩定。"},{"en":"The supply agreement includes volume commitments and delivery terms.","zh-TW":"供應協議包括數量承諾和交貨條款。"}]', NULL, NULL, 5, 6342, NULL),
(6343, 'supply and demand', '/səˈplaɪ ənd dɪˈmɑːnd/', 'noun', '{"zh-TW":["供求關係"],"en":["the relationship between the availability and desire for goods"]}', NULL, 'balance supply and demand / law of supply and demand', '[{"en":"Prices are determined by the law of supply and demand.","zh-TW":"價格由供求規律決定。"},{"en":"The shortage caused supply and demand to become severely imbalanced.","zh-TW":"短缺導致供求關係嚴重失衡。"}]', NULL, NULL, 5, 6343, NULL),
(6344, 'supply chain', '/səˈplaɪ tʃeɪn/', 'noun', '{"zh-TW":["供應鏈"],"en":["the network of businesses involved in producing and delivering a product"]}', NULL, 'global supply chain / supply chain disruption / supply chain resilience', '[{"en":"The pandemic exposed vulnerabilities in global supply chains.","zh-TW":"疫情暴露了全球供應鏈的脆弱性。"},{"en":"Diversifying the supply chain reduces dependency on single suppliers.","zh-TW":"多元化供應鏈降低了對單一供應商的依賴。"}]', '{"adjective":"supply-chain"}', NULL, 4, 6344, NULL),
(6345, 'supply chain disruption', '/səˈplaɪ tʃeɪn dɪsˈrʌpʃən/', 'noun', '{"zh-TW":["供應鏈中斷"],"en":["an interruption in the normal flow of goods in a supply chain"]}', NULL, 'manage supply chain disruption / supply chain disruption impact', '[{"en":"The pandemic caused significant supply chain disruptions worldwide.","zh-TW":"疫情在全球範圍內造成了重大的供應鏈中斷。"},{"en":"Companies built larger inventories to buffer against supply chain disruptions.","zh-TW":"公司建立了更大的庫存以緩衝供應鏈中斷的影響。"}]', NULL, NULL, 5, 6345, NULL),
(6346, 'supply chain management', '/səˈplaɪ tʃeɪn ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["供應鏈管理"],"en":["overseeing the flow of goods from supplier to customer"]}', NULL, 'supply chain management software / global supply chain management', '[{"en":"Supply chain management was disrupted by the pandemic.","zh-TW":"供應鏈管理因疫情而受到干擾。"},{"en":"Efficient supply chain management cuts delivery times.","zh-TW":"高效的供應鏈管理縮短了交貨時間。"}]', '{"adjective":"supply-chain"}', NULL, 5, 6346, NULL),
(6347, 'supply chain optimization', '/''sʌplaɪ tʃeɪn ˌɒptɪmaɪˈzeɪʃən/', 'noun', '{"zh-TW":["供應鏈優化"],"en":["the process of making a supply chain as efficient and cost-effective as possible"]}', NULL, 'achieve supply chain optimization / supply chain optimization strategy', '[{"en":"Supply chain optimization reduced production costs and improved delivery times.","zh-TW":"供應鏈優化降低了生產成本並改善了交付時間。"},{"en":"Data analytics plays a crucial role in modern supply chain optimization.","zh-TW":"數據分析在現代供應鏈優化中發揮著至關重要的作用。"}]', NULL, NULL, 5, 6347, NULL),
(6348, 'supply chain visibility', '/səˈplaɪ tʃeɪn ˌvɪzɪˈbɪlɪti/', 'noun', '{"zh-TW":["供應鏈可視性"],"en":["the ability to track products and components throughout the supply chain"]}', NULL, 'improve supply chain visibility / supply chain visibility tools', '[{"en":"Real-time data improves supply chain visibility across all stages.","zh-TW":"實時數據改善了各階段的供應鏈可視性。"},{"en":"Greater supply chain visibility reduces the risk of stockouts.","zh-TW":"更強的供應鏈可視性降低了缺貨風險。"}]', NULL, NULL, 5, 6348, NULL),
(6349, 'supply contract', '/səˈplaɪ ˈkɒntrækt/', 'noun', '{"zh-TW":["供應合約"],"en":["a formal agreement for a supplier to provide goods or services"]}', NULL, 'sign a supply contract / long-term supply contract', '[{"en":"The company signed a five-year supply contract with the manufacturer.","zh-TW":"公司與製造商簽署了五年供應合約。"},{"en":"A supply contract locks in pricing to protect against cost increases.","zh-TW":"供應合約鎖定了定價以防止成本增加。"}]', NULL, NULL, 5, 6349, NULL);